const raw = $input.item.json.body || $input.item.json;
const email = String(raw.email || '').trim().toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
  throw new Error('Validation Error: a valid lead email is required.');
}
const freeProviders = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com'];
const domain = email.split('@')[1];
const company = String(raw.company || domain.split('.')[0]).trim();
const segment = raw.segment || (freeProviders.includes(domain) ? 'solo_operator' : 'agency_team');
return {
  json: {
    contact_id: 'lead_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7),
    first_name: String(raw.first_name || raw.name || 'there').trim().split(' ')[0],
    last_name: String(raw.last_name || '').trim(),
    email,
    company,
    domain,
    segment,
    role: String(raw.role || 'Founder').trim(),
    trigger_event: String(raw.trigger_event || 'recent growth or launch activity').trim(),
    pain_point: String(raw.pain_point || 'campaign launches taking too long').trim(),
    notes: String(raw.notes || '').trim(),
    source: String(raw.source || 'manual').trim(),
    consent_basis: String(raw.consent_basis || 'legitimate_interest_b2b').trim(),
    received_at: new Date().toISOString()
  }
};

parameters.text:
=You are a senior new-business lead at an agency. Write one personalized cold email for the lead below.

Lead:
- First name: {{ $json.first_name }}
- Company: {{ $json.company }}
- Role: {{ $json.role }}
- Segment: {{ $json.segment }}
- Trigger: {{ $json.trigger_event }}
- Suspected pain: {{ $json.pain_point }}
- Notes: {{ $json.notes }}

Return ONLY valid JSON with this exact shape:
{
  "lead_score": <0-100 integer>,
  "segment_label": <"agency_team" | "solo_operator" | "enterprise" | "poor_fit">,
  "subject": <2-6 words, lowercase or sentence case, no exclamation mark>,
  "preview_text": <under 90 characters, adds context>,
  "body": <plain text, 60-110 words, 4 sentences maximum, no links, no calendar link, one soft reply CTA>,
  "followup_1": <plain text, 35-70 words, adds one proof point, no link unless permission was granted>,
  "followup_2": <plain text, 25-50 words, polite close, no guilt>
}

Rules:
- Sentence 1 references the trigger without flattery.
- Sentence 2 names the operational bottleneck.
- Sentence 3 gives one realistic peer proof point; mark it as illustrative if no verified metric exists.
- Sentence 4 asks for permission to send an asset or asks a one-line question.
- Never claim guaranteed results, never invent a client name, never use urgency.
- Write like a founder, not a marketing department. No emojis, no ALL CAPS.

parameters.jsCode:
const rawText = ($input.item.json.text || $input.item.json.output || '').toString();
let parsed;
try {
  const match = rawText.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(match ? match[0] : rawText);
} catch (error) {
  throw new Error('AI output was not valid JSON: ' + error.message);
}

const lead = $('Validate & Normalize Lead').item.json;
const spam = ['act now', '100% free', 'guaranteed returns', 'risk-free', 'limited time', 'make money fast', 'urgent'];
const body = String(parsed.body || '').trim();
const subject = String(parsed.subject || '').trim();
const reasons = [];
if (!subject || subject.length > 60) reasons.push('subject length must be 1-60 characters');
if (/[!]{1}/.test(subject)) reasons.push('subject contains an exclamation mark');
if (!body || body.split(/\s+/).length > 130) reasons.push('body must be 1-130 words');
if (/https?:\/\//i.test(body)) reasons.push('cold body must not contain a link');
if (/calendly\.com|cal\.com|hubspot\.com\/meetings/i.test(body)) reasons.push('cold body must not contain a calendar link');
if (spam.some(word => (subject + ' ' + body).toLowerCase().includes(word))) reasons.push('spam trigger phrase detected');
if (!parsed.followup_1 || !parsed.followup_2) reasons.push('both follow-ups are required');

return {
  json: {
    ...lead,
    lead_score: Number(parsed.lead_score || 0),
    segment_label: parsed.segment_label || lead.segment,
    subject,
    preview_text: String(parsed.preview_text || '').slice(0, 90),
    body,
    followup_1: String(parsed.followup_1 || '').trim(),
    followup_2: String(parsed.followup_2 || '').trim(),
    guardrail_passed: reasons.length === 0,
    guardrail_reasons: reasons,
    approval_token: 'apr_' + Math.random().toString(36).slice(2) + Date.now().toString(36),
    status: reasons.length === 0 ? 'pending_review' : 'blocked_by_guardrail'
  }
};
